{
  "sections": [
    {
      "key": "verdict",
      "title": "Verdict",
      "text": "Your dairy project is judged feasible. The lowest debt service coverage ratio is {{min_dscr}} and the payback period is about {{payback_months}} months, both well within safe limits."
    },
    {
      "key": "market",
      "title": "Market Overview",
      "text": "The village has roughly {{households}} households. There are no nearby competitors, so the market gap is small and you can reach most families directly or through a cooperative collection centre. Milk demand in the area is strong, and you can also sell to sweet shops."
    },
    {
      "key": "pricing",
      "title": "Pricing and Revenue",
      "text": "Selling fresh milk at the local market price will generate steady revenue. With a capacity of {{our_capacity}} litres per month, you can meet the needs of many households and earn enough to cover operating costs and loan repayments."
    },
    {
      "key": "risks",
      "title": "Key Risks",
      "text": "Possible risks include animal disease, fluctuations in milk price, and delays in receiving the government subsidy. The loan must be serviced on time, and the initial outlay for buffaloes ({{cost.animals}}) and the shed ({{cost.shed}}) is significant."
    },
    {
      "key": "path_to_yes",
      "title": "Path to Yes",
      "text": "Congratulations! Your plan already meets all feasibility criteria. No changes are needed to move forward."
    },
    {
      "key": "next_steps",
      "title": "Next Steps",
      "text": "- Apply for the PMEGP loan of {{loan}} and claim the subsidy of {{subsidy}}. - Arrange the purchase of buffaloes costing {{cost.animals}} and build the shed costing {{cost.shed}}. - Use your own contribution of {{own_contribution}} to cover part of the {{project_cost}} project cost. - Set up a milk collection system and start selling to households and sweet shops. - Keep detailed records of sales, expenses and loan payments to monitor the DSCR and payback progress."
    }
  ],
  "swot": {
    "strengths": [
      "a capital subsidy under PMEGP",
      "Very low competition in the area",
      "Strong debt service coverage ratio ({{min_dscr}})"
    ],
    "weaknesses": [
      "High upfront cost for animals and shed ({{cost.animals}} + {{cost.shed}})",
      "Dependence on a bank loan for most of the funding"
    ],
    "opportunities": [
      "Growing milk demand among {{households}} households",
      "Possibility to expand to nearby villages or value‑added products"
    ],
    "threats": [
      "Animal health issues could reduce production",
      "Market price changes could affect profit margins"
    ]
  }
}
